+import assert from 'node:assert/strict';
+import { after, before, describe, it } from 'node:test';
+import { parseCsvShipments } from '../src/lib/csv.ts';
+import { api, startTestServer, type TestServer } from './helpers.ts';
+
+const HEADER = 'tracking,carrier,service,name,street,zip,city,country,phone';
+
+describe('CSV parser with quoted fields', () => {
+  it('keeps commas inside quotes in one column', () => {
+    const rows = parseCsvShipments(
+      [HEADER, 'RR987654326AT,OEPOST,standard,"Müller, Hans",Herrengasse 12,8010,Graz,AT,+43 1'].join('\n'),
+    );
+    assert.equal(rows[0].recipient.name, 'Müller, Hans');
+    assert.equal(rows[0].recipient.street, 'Herrengasse 12');
+    assert.equal(rows[0].recipient.zip, '8010');
+    assert.equal(rows[0].recipient.phone, '+43 1');
+  });
+
+  it('handles escaped quotes, CRLF and unquoted rows', () => {
+    const rows = parseCsvShipments(
+      [HEADER, 'A,DHL,,"Anna ""Annie"", Dr.",S 1,1010,Wien,,', 'B,DHL,,Bob,S 2,1020,Wien,DE,'].join('\r\n'),
+    );
+    assert.equal(rows.length, 2);
+    assert.equal(rows[0].recipient.name, 'Anna "Annie", Dr.');
+    assert.equal(rows[1].recipient.country, 'DE');
+  });
+});
+
+describe('POST /import with quoted commas', () => {
+  let srv: TestServer;
+  before(async () => {
+    srv = await startTestServer();
+  });
+  after(async () => {
+    await srv.close();
+  });
+
+  it('imports a recipient named "Müller, Hans"', async () => {
+    const csv = [HEADER, 'RR987654326AT,OEPOST,standard,"Müller, Hans",Herrengasse 12,8010,Graz,AT,'].join('\n');
+    const res = await api(srv.url, 'POST', '/import', csv);
+    assert.equal(res.status, 200);
+    assert.deepEqual(res.body.errors, []);
+    assert.equal(res.body.created, 1);
+  });
+});
